def translate_line(text):
    """Translate a single line of text"""
    for vietnamese, english in translations.items():
        if vietnamese in text:
            text = text.replace(vietnamese, english)
    return text

# Read the input file
with open('raw_data.txt', 'r', encoding='utf-8') as f:
    lines = f.readlines()

# Translate each line
translated_lines = []
for line in lines:
    translated_lines.append(translate_line(line))

# Write to output file
with open('raw_data_english.txt', 'w', encoding='utf-8') as f:
    f.writelines(translated_lines)

print("Translation complete! Output saved to raw_data_english.txt")
